const loadingModal=action=>{const $el=document.getElementById("modal2");const $body=document.body;if($el){action==="show"?$body.classList.add("loading"):$body.classList.remove("loading");action==="show"?$el.style.display="block":$el.style.display="none"}};const sendPostMessage=(idSession,url)=>{const $elIframe=document.getElementById("iframeVisor");if($elIframe)$elIframe.contentWindow.postMessage(idSession,url)};function wizardTabNavegarStep(idWidgetVarWizard,numberSterp){const wizard=PF(idWidgetVarWizard);if(wizard){wizard?.loadStep(wizard?.cfg?.steps[numberSterp])}}window.addEventListener("popstate",function(event){console.log("Navegación detectada: hacia adelante o hacia atrás");document.querySelectorAll(".ui-button .ui-state-loading").forEach(btn=>btn.classList.remove("ui-state-loading"))});document.addEventListener("DOMContentLoaded",event=>{loadingModal("hide")});function validarCambioTabFormularioDeclaracionV2(){const el=document.getElementById("formularioDeclaracionV2:tabView");const elUl=el?el.querySelectorAll("ul"):null;const elTabActi=elUl?elUl[0].querySelector(".ui-tabs-selected"):null;if(elTabActi&&elTabActi.innerHTML.indexOf("DEOLACEC")!=-1){return validarActividadPrincipal()}return true}var disabledInput=(disabled,idDiv)=>{const $elDivParent=document.getElementById(idDiv);if($elDivParent){$elDivParent.querySelectorAll("input").forEach(elInput=>{if(elInput)elInput.readOnly=disabled})}};function validarActividadPrincipal(){const tableActividades=document.getElementById("formularioDeclaracionV2:tabView:dataTableActividadesEconomicas");if(tableActividades){const columnsTable=tableActividades.getElementsByTagName("td");if(!columnsTable){return true}let index=columnsTable.length;for(let i=0;i<index;i++){if(columnsTable[i].innerHTML.indexOf("Principal")!=-1){return true}}callBackAlertActividadPrincipal();return false}}function cargaContenidoAcordion(envent,idWVAcordion){const $el=envent?.target?.parentElement?.tagName;if($el==="BUTTON")return;const indiceActivo=PF(idWVAcordion);if(indiceActivo){const indexActive=indiceActivo?.cfg?.active;const idElement=indiceActivo?.headers[indexActive]?.lastChild?.lastChild?.firstChild?.id;try{if(idElement)document.getElementById(idElement).onclick()}catch(error){}}}